import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"16、【豫】 坤下震上","description":"周易尚氏學 - 16、【豫】 坤下震上","frontmatter":{"title":"16、【豫】 坤下震上","description":"周易尚氏學 - 16、【豫】 坤下震上"},"headers":[],"relativePath":"classics/shangshi/021.md","filePath":"classics/shangshi/021.md"}'),s={name:"classics/shangshi/021.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_16、【豫】-坤下震上" tabindex="-1">16、【豫】 坤下震上 <a class="header-anchor" href="#_16、【豫】-坤下震上" aria-label="Permalink to “16、【豫】 坤下震上”">​</a></h1><p>雷出地上。得眾志行。故豫。豫。和樂也。歸藏作分。言震雷上出。與地分離也。又一陽界於五陰之間。使上下分別。與周易義異。震為君。故曰建侯。與屯同義。坤為師。順以動。故利行師。</p><p>彖曰。豫。剛應而志行。順以動豫。豫順以動。故天地如之。而況建侯行師乎。天地以順動。故日月不過。而四時不忒。聖人以順動。則刑罰清而民服。豫之時義大矣哉。</p><p>艮為天。坤為地。艮為日。坎為月。順故不過不忒。坎為刑罰。坤為民。坤順故刑罰清而民服。艮為時。震卦數四。故曰四時。坎為聖。(虞氏逸象)李鼎祚以震為聖。非。</p><p>象曰。雷出地奮。豫。先王以作樂崇德。殷薦之上帝。以配祖考。</p><p>震為樂。為仁德。為帝。為薦。薦進也。殷盛也。艮為祖考。(象失傳。只易林知之。實小過六二過其祖。即以艮為祖。詳焦氏易詁。)古帝王作樂。皆以象其功德。用以郊天。使祖考配享。雷出地奮。聲容象之。故先王取以為法。震為王。</p><p>初六。嗚豫。兇。</p><p>初應四。四震為鳴。故曰鳴豫。爻在此而象在應。如蒙三之金夫。泰二之包巟憑河。及此為易之通例。自此例不明。於是明夷初九之飛及翼。皆以離為象矣。初六得敵。不能應四。故兇。</p><h3 id="象曰。初六鳴豫。志窮兇也。" tabindex="-1">象曰。初六鳴豫。志窮兇也。 <a class="header-anchor" href="#象曰。初六鳴豫。志窮兇也。" aria-label="Permalink to “象曰。初六鳴豫。志窮兇也。”">​</a></h3><p>窮者極也。初為二三所隔。應四難。故曰志窮。</p><p>六二。介於石。不終日。貞吉。</p><p>釋文雲。介古文作硋。鄭古八反。雲磨硋也。馬作抯。雲觸小石聲。案說文。抯刮也。古黠切。廣韻揩抯物也。音戛。揩抯即磨硋。皆觸堅不相入之聲。又莊子馬蹄篇。加之以衡扼。齊之以月題。而馬知介倪。陸雲介徐古八反。亦音戛。介者觸。倪睨同。介倪者。即馬因感觸月題等物之磨硋。因而睥睨也。是莊子亦以介為觸。然則硋抯介音義並同。蓋非觸堅。不能有磨戛之聲。然則介於石即觸於石。艮為石。二前遇之。故觸於石。易之道。異性為類。同性相敵。二五無應。承乘皆陰。如觸於石之不相入。觸石不入。故君子見幾而作。不俟終日也。舊解詁硋字是。而義則不詳。須知硋於石。乃危辭。以形容二之失類。故系雲介如石焉。寧用終日。斷可識矣。艮為終日。易林大過之艮雲。終日至暮。不離其鄉。以艮為終日。坎為暮也。夫居中位。而又能危惕自警。故貞吉也。宋翔鳳以說文無硋字。有抯。便謂硋為訛字。豈知晉孔坦答劉聰求降書曰。何知幾之先覺。硋石之易悟。桓溫傳。亦曰硋如石所以成務。不止鄭作硋也。</p><h3 id="象曰。不終日。貞吉。以中正也。" tabindex="-1">象曰。不終日。貞吉。以中正也。 <a class="header-anchor" href="#象曰。不終日。貞吉。以中正也。" aria-label="Permalink to “象曰。不終日。貞吉。以中正也。”">​</a></h3><p>二當位。故中正。</p><p>六三。盱豫。悔。遲有悔。</p><p>說文。盱。張目也。爾雅。盱憂也。又詩小雅。云何盱矣。鄭箋病也。艮為視。(象失傳。祇易及易林用之。詳焦氏易詁)。坤為病。故曰盱。諸爻獨三得承陽。然失位。故睢盱上視。有憂悔也。艮止故遲。有又通。遲有悔者。言遲疑不決。又有悔也。盱豫句。悔一字句。</p><h3 id="象曰。盱豫有悔。位不當也。" tabindex="-1">象曰。盱豫有悔。位不當也。 <a class="header-anchor" href="#象曰。盱豫有悔。位不當也。" aria-label="Permalink to “象曰。盱豫有悔。位不當也。”">​</a></h3><p>位不當。釋盱豫之故。</p><p>九四。由豫。大有得。勿疑。朋盍簪。</p><p>盂子。由由然與之偕。注。由由。自得之貌。由豫者。從容和樂也。坎為疑。上下四陰附之。陽遇陰則通。故曰大有得勿疑。陽以陰為朋。盍合也。簪與笄同。所以括髮。朋盍簪言群陰歸四。有若簪之括髮也。臧庸雲。象盍簪者。取一陽橫貫於五陰之中。可謂觀象獨深。又杜詩。盍簪喧櫪馬。言群馬縶於一槓之上。故以盍簪為喻。此語解易。可謂明白如晝矣。艮為簪。易林。恆之鹹雲。簪短帶長。以鹹艮為簪。復之節語同。亦以節之互艮為簪。凡易林象。無不本於易。子夏傳為韓嬰作。在漢易為最古。即作簪。故焦氏亦讀為簪。與子夏傳同。至東漢則多改字，其詳皆在焦氏易詁中。(後之人於笄簪括髮之形象。茫昧失考。故於易象維妙維肖之朋盍簪三字。皆不知其故。而尤以謂漢以前無簪名者為失考。儀禮簪衣於裳。韓非子周主亡玉簪。李斯諫逐客。宛珠之簪。謂漢以前無者非也。)</p><h3 id="象曰。由豫大有得。志大行也。" tabindex="-1">象曰。由豫大有得。志大行也。 <a class="header-anchor" href="#象曰。由豫大有得。志大行也。" aria-label="Permalink to “象曰。由豫大有得。志大行也。”">​</a></h3><p>志謂坎。上下五陰皆孚於四。故曰志大行。</p><p>六五。貞疾。恆不死。</p><p>坎為疾。震生故曰不死。五以陰柔處尊位。乘剛勢逆。故常疾。然久而不死。以處中位也。如齊田得民。姜亦不遽亡也。</p><h3 id="象曰。六五貞疾。乘剛也。" tabindex="-1">象曰。六五貞疾。乘剛也。 <a class="header-anchor" href="#象曰。六五貞疾。乘剛也。" aria-label="Permalink to “象曰。六五貞疾。乘剛也。”">​</a></h3><p>恆不死。中未亡也。中未亡之故。以得中故也。</p><p>上六。冥豫。成有渝。無咎。</p><p>冥昧不事事。功之成者。必漸隳矣。故曰成有渝。然當位。目前雖無大咎。久則禍至。故象曰何可長。</p><h3 id="象曰。冥豫在上。何可長也。" tabindex="-1">象曰。冥豫在上。何可長也。 <a class="header-anchor" href="#象曰。冥豫在上。何可長也。" aria-label="Permalink to “象曰。冥豫在上。何可長也。”">​</a></h3><p>何可長。言不足恃。</p>',30)])])}const f=e(s,[["render",t]]);export{_ as __pageData,f as default};
